import { corsHeaders } from "npm:@supabase/supabase-js@2/cors";
import { createClient } from "npm:@supabase/supabase-js@2";
import { z } from "npm:zod@3";
import { gerarJsonEmFluxo, limitarTexto } from "../_shared/aiStream.ts";
import { CAMPOS_APR, circunstanciaTecnicaApr, cenariosValidosApr, formulariosCompativeisApr, classificacoesSalvasApr, recalcularLinhaApr } from "../_shared/aprErgoIa.ts";
import { SITUACOES_APR, TIPOS_APR, ESTIMATIVAS_APR, INTENSIDADES_APR, SEVERIDADES_APR, EXIGENCIAS_APR, MEDIDAS_APR, exigenciasDaSituacao } from "../_shared/aprErgoPlanilha.ts";

const Body = z.object({ registroId: z.string().uuid(), relato: z.string().trim().min(10).max(30000),
  criterios: z.object({ duracao: z.array(z.string().max(500)).length(5), intensidade: z.array(z.string().max(500)).length(5), fatores: z.array(z.tuple([z.string().max(100), z.array(z.string().max(1000))])).max(10) }),
  base: z.array(z.object({ nome: z.string().max(255), tipo: z.enum(["pdf", "texto"]), data: z.string().max(14000000) })).max(6),
});
// Saída estruturada estrita não aceita aspas duplas em literais de enum: normaliza para ' e reverte no pós-processamento.
const semAspas = (s: string) => s.replace(/["“”]/g, "'");
const opc = (v: readonly string[]) => ({ type: "string", enum: ["", ...new Set(v.map(semAspas))] });
const schema = { type: "object", properties: {
  cabecalho: { type: "object", properties: { atividades: { type: "string" }, ambiente: { type: "string" } } },
  linhas: { type: "array", items: { type: "object", properties: {
    funcao_id: { type: "string" }, funcao_ids: { type: "array", items: { type: "string" } }, cenario: { type: "string" }, circunstancia: { type: "string" }, recomendacoes: { type: "string" }, codigo_aep: { type: "string" }, formulario_aep_id: { type: "string" },
    situacao: opc(SITUACOES_APR), exigencia: opc(EXIGENCIAS_APR.map((e) => e[1])), tipo: opc(TIPOS_APR),
    medidas: { type: "array", items: { type: "string", enum: [...new Set(MEDIDAS_APR.map(semAspas))] } },
    estimativa: opc(ESTIMATIVAS_APR.map((e) => e[0])), intensidade: opc(INTENSIDADES_APR.map((e) => e[0])), severidade: opc(SEVERIDADES_APR.map((e) => e[1])),
  } } }, observacoes: { type: "string" },
} };
const TABELA = { situacao_exigencia_esocial: EXIGENCIAS_APR, estimativa_tempo: ESTIMATIVAS_APR, intensidade_nivel: INTENSIDADES_APR, severidade: SEVERIDADES_APR.map(([l, d, i]) => [l, d, i]) };
const prompt = `Você é ergonomista elaborando APR-ERGO conforme a planilha Anexo 03. Produza análise técnica formal da atividade real: relação entre atividade, exigência ergonômica, condição e repercussão; recomendações específicas na fonte, processo, organização, mobiliário, equipamentos e método. Não invente atividades, controles existentes, exposições, medições ou condições. Referências são contexto técnico, não prova de fatos. Gere TODOS os cenários ergonômicos necessários das atividades reais de CADA função, sem limite fixo por função ou setor (não limitar a três nem a oito). Quando houver várias funções, analise suas atividades EM CONJUNTO em UMA ÚNICA planilha: reúna atividades, condições e exigências comuns, sem separar ou repetir cenários por função. Inclua diferenças relevantes somente quando gerarem riscos distintos. Não fragmente artificialmente riscos nem crie cenários sem fundamento técnico. Cada linha deve indicar funcao_ids com os IDs exatos de todas as funções abrangidas; para uma única função pode indicar funcao_id. circunstancia deve descrever a tarefa real, fonte de exigência ergonômica e condições de execução; NUNCA inclua nomes de funções nessa coluna. Os vínculos ficam exclusivamente nos IDs internos. Textos objetivos, completos, sem mencionar cadastro, IA ou fontes dentro das células.
Cabeçalho: atividades deve reunir as descrições das atividades de TODAS as funções do SETOR em um resumo técnico único de aproximadamente quatro linhas (até 650 caracteres); não se limitar à função mencionada no relato. ambiente deve ser uma descrição geral objetiva e breve (até 400 caracteres), baseada na descricao_ambiente do setor, relato e Base; não suponha instalações ou condições ausentes.
Use a Base para interpretar os critérios de exposição e severidade no contexto real, mantendo as opções e fórmulas da planilha abaixo; não crie outra matriz. A conduta administrativa é inserida pelo sistema conforme a classificação calculada. Para Alto e Muito Alto, recomendacoes deve ficar vazio: o sistema insere SOMENTE a conduta da matriz, sem sugestões ou observações extras. Nos demais níveis, pode conter sugestões práticas específicas para a atividade, sem repetir a conduta administrativa.
MOVIMENTAÇÃO MANUAL DE CARGAS: analise as atividades de CADA função do setor e identifique levantamento, transporte, sustentação, movimentação ou descarga manual de cargas. Quando aplicável, crie as linhas pertinentes (situacao "Movimentação Manual de Cargas" ou outra coerente) conforme as atividades reais. Para essa análise use EXCLUSIVAMENTE os arquivos da Base "Instruções de Ergonomia para Levantamento, Transporte e Descarga Manual de Cargas – Corredor Norte" e "Manual de Sinalização Alivie a Carga" (identifique-os pelo nome, mesmo abreviado); não use fontes externas. Relacione suas diretrizes às funções, tarefas, cargas, condições de execução e medidas preventivas nas recomendações. Se esses arquivos não estiverem na Base, informe em observacoes.
PREENCHIMENTO: preencha todas as células aplicáveis usando empresa, setor, funções, AEP e Base. Estimativa técnica só com fundamento suficiente, identificada no texto como "(estimativa)". Nunca invente pesos, frequências, distâncias ou condições específicas sem evidência.
Regras da planilha: cenario é o número sequencial da linha (1, 2, 3...). situacao é UMA opção da lista. exigencia deve ser uma exigência da TABELA pertencente à situação escolhida. tipo é uma das opções (Fisico, Organizacional, Cognitivo, Ambiental) coerente com a situação. medidas: selecione somente controles da lista que o relato, a Base ou a AEP confirmem existir; nenhum se não confirmado. estimativa, intensidade e severidade: escolha exatamente uma opção da lista somente quando o relato, a Base ou a AEP sustentarem a escolha para a atividade real; caso contrário deixe vazio. Perfil e Classificação do Risco NÃO são preenchidos por você: o sistema calcula pelas fórmulas da planilha.
Os formulários AEP são somente os compatíveis com esta empresa, contrato, setor e funções. Para cada linha indique codigo_aep e formulario_aep_id SOMENTE se o fator marcado corresponde à mesma atividade/função relatada; caso contrário ambos vazios. Marcas D1-D5 e I1-I5 da AEP equivalem, pela mesma ordem, às opções de estimativa e intensidade e prevalecem. Não interprete A1-A5 (IDs de atividade) como severidade. observacoes deve explicar lacunas reais das classificações para revisão fora da tabela.`;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  const json = (error: string, status: number) => new Response(JSON.stringify({ error }), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });
  try {
    const url = Deno.env.get("SUPABASE_URL"), anon = Deno.env.get("SUPABASE_ANON_KEY"), key = Deno.env.get("GEMINI_API_KEY");
    if (!url || !anon) return json("Serviço indisponível.", 500);
    if (!key) return json("GEMINI_API_KEY não configurada. Crie a chave em https://aistudio.google.com/apikey e cadastre o secret nas Edge Functions do Supabase.", 500);
    const auth = req.headers.get("Authorization") || "";
    const sb = createClient(url, anon, { global: { headers: { Authorization: auth } } });
    const { data: claims, error: authError } = await sb.auth.getClaims(auth.replace("Bearer ", ""));
    if (authError || !claims?.claims?.sub) return json("Sessão expirada. Entre novamente.", 401);
    const parsed = Body.safeParse(await req.json());
    if (!parsed.success) return json("Verifique o relato e os arquivos enviados (até 6).", 400);
    const body = parsed.data;
    if (body.base.reduce((n, b) => n + b.data.length, 0) > 24000000) return json("Os arquivos excedem o tamanho permitido para análise. Reduza os arquivos.", 400);
    const { data: doc, error: docError } = await sb.from("documentos").select("empresa_id, contrato_id, empresa_nome, draft_snapshot").eq("id", body.registroId).eq("tipo", "APR-ERGO").single();
    if (docError || !doc?.empresa_id || !doc?.contrato_id) return json("Registro APR-ERGO indisponível.", 404);
    const setorId = doc.draft_snapshot?.setor_id;
    if (typeof setorId !== "string") return json("O registro não possui setor vinculado.", 400);
    const { data: setor, error: setorError } = await sb.from("setores").select("id, nome_setor, ghe_ges, descricao_ambiente, funcoes(id, nome_funcao, descricao_atividades)").eq("id", setorId).eq("empresa_id", doc.empresa_id).eq("contrato_id", doc.contrato_id).single();
    if (setorError || !setor) return json("O setor não corresponde à empresa e ao contrato.", 400);
    const funcaoId = doc.draft_snapshot?.funcao_id;
    const selecionadas = typeof funcaoId === "string" ? [funcaoId] : Array.isArray(doc.draft_snapshot?.funcao_ids) ? doc.draft_snapshot.funcao_ids : null;
    if (selecionadas) {
      if (selecionadas.some((id: unknown) => typeof id !== "string" || !setor.funcoes.some((f: { id: string }) => f.id === id))) return json("Função não pertence ao setor desta APR-ERGO.", 400);
      setor.funcoes = setor.funcoes.filter((f: { id: string }) => selecionadas.includes(f.id));
      if (!setor.funcoes.length) return json("A função não pertence ao setor desta APR-ERGO.", 400);
    }
    const formularios = [];
    for (let offset = 0; ; offset += 100) {
      const { data, error } = await sb.from("formularios_aep").select("id, setor_ids, dados, updated_at").eq("empresa_id", doc.empresa_id).eq("contrato_id", doc.contrato_id).contains("setor_ids", [setorId]).order("updated_at", { ascending: false }).range(offset, offset + 99);
      if (error) return json("Não foi possível consultar a AEP. Tente novamente.", 500);
      formularios.push(...(data || []));
      if (!data || data.length < 100) break;
    }
    const compativeis = formulariosCompativeisApr(formularios, setorId, setor.funcoes.map((f: { id: string }) => f.id)).slice(0, 5);
    const content: unknown[] = body.base.filter((b) => b.tipo === "pdf").map((b) => ({ type: "input_file", filename: b.nome, file_data: `data:application/pdf;base64,${b.data}` }));
    content.push({ type: "input_text", text: `RELATO: ${body.relato}\nEMPRESA: ${doc.empresa_nome}\nSETOR: ${JSON.stringify(setor)}\nAEP COMPATÍVEL: ${JSON.stringify(compativeis)}\nTABELA APR-ERGO: ${JSON.stringify(TABELA)}\nCRITÉRIOS AEP: ${JSON.stringify(body.criterios)}\nBASE: ${body.base.filter((b) => b.tipo === "texto").map((b) => `${b.nome}\n${limitarTexto(b.data, 40000)}`).join("\n")}` });
    return await gerarJsonEmFluxo({ req, corsHeaders, key, systemPrompt: prompt, userContent: content, schemaName: "apr_ergo", schema,
      posProcessar: (output) => {
        const fontes = new Set<string>();
        const candidatas = (output.linhas || []).map((l: Record<string, any>) => {
          const ids = [...new Set<string>(Array.isArray(l.funcao_ids) && l.funcao_ids.length ? l.funcao_ids : typeof l.funcao_id === "string" ? [l.funcao_id] : [])];
          const funcoes = setor.funcoes.filter((f: { id: string }) => ids.includes(f.id));
          const funcao = funcoes.length === 1 ? funcoes[0] : undefined;
          const f = compativeis.find((f) => f.id === l.formulario_aep_id && f.dados?.funcoes?.length === 1 && f.dados.funcoes[0] === funcao?.id);
          const marcas = f?.dados?.reconhecimento?.marcas?.[l.codigo_aep];
          if (marcas) fontes.add(f.id);
          const um = (v: unknown, ops: readonly string[]) => typeof v === "string" && v ? ops.find((o) => o === v || semAspas(o) === semAspas(v)) || "" : "";
          const situacao = um(l.situacao, SITUACOES_APR);
          const salvas = classificacoesSalvasApr(marcas || {});
          const medidas = [...new Set((Array.isArray(l.medidas) ? l.medidas : []).map((m: unknown) => um(m, MEDIDAS_APR)).filter(Boolean))].join("; ");
          const calculada = recalcularLinhaApr({ ...Object.fromEntries(CAMPOS_APR.map((k) => [k, typeof l[k] === "string" ? l[k] : ""])),
            funcao_id: funcao?.id || "", funcao_ids: ids, funcao_nome: funcoes.map((f: { nome_funcao: string }) => f.nome_funcao).join("; "), setor_id: setorId,
            circunstancia: circunstanciaTecnicaApr(l.circunstancia, setor.funcoes.map((f: { nome_funcao: string }) => f.nome_funcao)),
            situacao, exigencia: um(l.exigencia, exigenciasDaSituacao(situacao)), tipo: um(l.tipo, TIPOS_APR), medidas,
            estimativa: salvas.estimativa || um(l.estimativa, ESTIMATIVAS_APR.map((e) => e[0])),
            intensidade: salvas.intensidade || um(l.intensidade, INTENSIDADES_APR.map((e) => e[0])),
            severidade: um(l.severidade, SEVERIDADES_APR.map((e) => e[1])), perfil: "", classificacao: "", fotos: [] } as any);
          return calculada;
        });
        const linhas = cenariosValidosApr(candidatas, setorId, setor.funcoes.map((f: { id: string }) => f.id)).map((l, i) => ({ ...l, cenario: String(i + 1) }));
        return { linhas, fontes_aep: [...fontes], observacoes: output.observacoes || "", cabecalho: { atividades: typeof output.cabecalho?.atividades === "string" ? output.cabecalho.atividades.trim() : "", ambiente: typeof output.cabecalho?.ambiente === "string" ? output.cabecalho.ambiente.trim() : "" } };
      },
    });
  } catch (e) {
    if ((e as Error)?.name === "AbortError") return new Response(null, { status: 499, headers: corsHeaders });
    return json("Não foi possível gerar a análise. Seus dados foram mantidos.", 500);
  }
});

// Chamada à IA (Google Gemini) com resposta em fluxo NDJSON para o navegador.
// Motivo: gerações longas excediam o tempo ocioso da Edge Function quando a
// resposta era montada inteira antes de responder. O cliente recebe "ping"
// periódicos e, ao final, {type:"result"} ou {type:"error"}.
// A chave fica só em Deno.env (GEMINI_API_KEY). Nunca no frontend nem nos logs.

const MAX_TEXT_CHARS = 180_000;
const MAX_ANEXO_BYTES_TOTAL = 18 * 1024 * 1024;

/** Modelos do plano gratuito (texto, PDF e imagem). Só há fallback em 404 de modelo, nunca para burlar cota. */
export const GEMINI_MODELO_PADRAO = "gemini-2.5-flash";
export const GEMINI_MODELO_VISAO = "gemini-2.5-flash";
const GEMINI_MODELOS_GRATUITOS = ["gemini-2.5-flash", "gemini-2.0-flash"] as const;

/** Limita o tamanho de um texto preservando início e fim. */
export function limitarTexto(texto: string, max = MAX_TEXT_CHARS): string {
  if (texto.length <= max) return texto;
  const meio = Math.floor(max / 2);
  return `${texto.slice(0, meio)}\n\n[... conteúdo extenso resumido por limite de contexto ...]\n\n${texto.slice(-meio)}`;
}

/** Reduz JSON grande truncando strings longas e listas extensas. */
export function compactarContexto(valor: unknown, maxStr = 4000, maxArr = 60): unknown {
  if (typeof valor === "string") return valor.length > maxStr ? valor.slice(0, maxStr) + "…" : valor;
  if (Array.isArray(valor)) return valor.slice(0, maxArr).map((v) => compactarContexto(v, maxStr, maxArr));
  if (valor && typeof valor === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(valor)) out[k] = compactarContexto(v, maxStr, maxArr);
    return out;
  }
  return valor;
}

/** Mantém anexos dentro de um orçamento total de bytes (base64). */
export function limitarAnexos<T extends { data?: string }>(lista: T[], max = 10): T[] {
  let total = 0;
  const out: T[] = [];
  for (const a of lista.slice(0, max)) {
    const size = (a?.data?.length || 0) * 0.75;
    if (!a?.data || total + size > MAX_ANEXO_BYTES_TOTAL) continue;
    total += size;
    out.push(a);
  }
  return out;
}

/** Ajusta schema ao modo estrito: objetos fechados e todas as chaves obrigatórias. */
export function schemaEstrito(schema: any): any {
  if (Array.isArray(schema)) return schema.map(schemaEstrito);
  if (!schema || typeof schema !== "object") return schema;
  const out: any = {};
  for (const [k, v] of Object.entries(schema)) {
    out[k] = k === "properties"
      ? Object.fromEntries(Object.entries(v as any).map(([pk, pv]) => [pk, schemaEstrito(pv)]))
      : schemaEstrito(v);
  }
  if (out.type === "object" && out.properties) {
    out.additionalProperties = false;
    out.required = Object.keys(out.properties);
  }
  return out;
}

const TIPO_GEMINI: Record<string, string> = {
  object: "OBJECT", string: "STRING", number: "NUMBER", integer: "INTEGER",
  boolean: "BOOLEAN", array: "ARRAY", null: "NULL",
};

/** Remove campos rejeitados e normaliza tipos para o responseSchema do Gemini. */
function schemaParaGemini(schema: any): any {
  if (Array.isArray(schema)) return schema.map(schemaParaGemini);
  if (!schema || typeof schema !== "object") return schema;
  const out: any = {};
  for (const [k, v] of Object.entries(schema)) {
    if (k === "$schema" || k === "$id" || k === "examples" || k === "default" || k === "additionalProperties") continue;
    if (k === "type" && typeof v === "string") {
      out.type = TIPO_GEMINI[v.toLowerCase()] || v.toUpperCase();
      continue;
    }
    if (k === "type" && Array.isArray(v)) {
      out.type = v.map((t) => (typeof t === "string" ? (TIPO_GEMINI[t.toLowerCase()] || t.toUpperCase()) : t));
      continue;
    }
    out[k] = k === "properties"
      ? Object.fromEntries(Object.entries(v as any).map(([pk, pv]) => [pk, schemaParaGemini(pv)]))
      : schemaParaGemini(v);
  }
  return out;
}

export function obterChaveGemini(): string | null {
  const key = Deno.env.get("GEMINI_API_KEY")?.trim();
  return key || null;
}

export function mensagemSemChaveGemini(): string {
  return "GEMINI_API_KEY não configurada. Crie uma chave gratuita em https://aistudio.google.com/apikey e cadastre o secret GEMINI_API_KEY nas Edge Functions do Supabase.";
}

function mensagemAmigavel(status: number, detalhe: string, statusGrpc?: string): string {
  const texto = `${detalhe} ${statusGrpc || ""}`.toLowerCase();
  if (status === 429 || statusGrpc === "RESOURCE_EXHAUSTED" || /resource.?exhausted|quota|rate.?limit|too many/i.test(texto)) {
    return "A cota gratuita da API Gemini está indisponível ou o limite de requisições foi atingido. Aguarde e tente novamente. Nenhuma cobrança automática é feita por este sistema.";
  }
  if (status === 403 || /api.?key.?not.?valid|permission.?denied|consumer/i.test(texto)) {
    return "A chave GEMINI_API_KEY é inválida ou não tem permissão para o Gemini. Gere outra em https://aistudio.google.com/apikey e atualize o secret no Supabase.";
  }
  if (status === 400) {
    return "Os dados enviados não puderam ser processados pela IA. Reduza anexos ou textos muito extensos e tente novamente.";
  }
  if (status === 404) {
    return "O modelo de IA configurado não está disponível neste momento. Tente novamente mais tarde.";
  }
  if (status >= 500 || statusGrpc === "UNAVAILABLE") {
    return "O serviço Gemini está temporariamente indisponível. Tente novamente em instantes.";
  }
  return detalhe || "A geração com IA não pôde ser concluída.";
}

function extrairBase64(dataUrlOuBase64: string): { mime: string; data: string } | null {
  const m = String(dataUrlOuBase64 || "").match(/^data:([^;]+);base64,(.+)$/i);
  if (m) return { mime: m[1], data: m[2] };
  if (/^[A-Za-z0-9+/=\s]+$/.test(dataUrlOuBase64) && dataUrlOuBase64.length > 32) {
    return { mime: "application/octet-stream", data: dataUrlOuBase64.replace(/\s+/g, "") };
  }
  return null;
}

/** Converte o formato já usado pelas funções (input_text/image/file) para partes Gemini. */
export function partesGeminiDeConteudo(userContent: unknown[]): { textParts: any[]; inlineParts: any[] } {
  const textParts: any[] = [];
  const inlineParts: any[] = [];
  for (const item of userContent || []) {
    if (!item || typeof item !== "object") continue;
    const p = item as Record<string, any>;
    if (p.type === "input_text" || p.type === "text") {
      const text = String(p.text || "");
      if (text) textParts.push({ text });
      continue;
    }
    if (p.type === "input_image" || p.type === "image_url") {
      const raw = typeof p.image_url === "string" ? p.image_url : p.image_url?.url || p.data || "";
      const parsed = extrairBase64(raw);
      if (parsed) inlineParts.push({ inline_data: { mime_type: parsed.mime.startsWith("image/") ? parsed.mime : "image/jpeg", data: parsed.data } });
      continue;
    }
    if (p.type === "input_file" || p.type === "file") {
      const raw = p.file_data || p.file?.file_data || p.data || "";
      const parsed = extrairBase64(raw);
      const nome = String(p.filename || p.file?.filename || "anexo.pdf").toLowerCase();
      const mime = parsed?.mime && parsed.mime !== "application/octet-stream"
        ? parsed.mime
        : nome.endsWith(".pdf") ? "application/pdf" : (parsed?.mime || "application/pdf");
      if (parsed) inlineParts.push({ inline_data: { mime_type: mime, data: parsed.data } });
      continue;
    }
  }
  return { textParts, inlineParts };
}

function sanitizarErroParaLog(texto: string, key?: string): string {
  let s = String(texto || "").slice(0, 500);
  if (key) s = s.split(key).join("[redacted]");
  return s.replace(/key[=:]\s*[A-Za-z0-9_\-]{8,}/gi, "key=[redacted]");
}

async function chamarGeminiJson(opts: {
  key: string;
  model: string;
  systemPrompt: string;
  userContent: unknown[];
  schema: unknown;
  signal?: AbortSignal;
}): Promise<{ ok: true; text: string } | { ok: false; status: number; error: string; retryable: boolean }> {
  const { textParts, inlineParts } = partesGeminiDeConteudo(opts.userContent);
  const parts = [...inlineParts, ...textParts];
  if (!parts.length) parts.push({ text: "Gere a resposta JSON solicitada." });

  const body = {
    systemInstruction: { parts: [{ text: opts.systemPrompt }] },
    contents: [{ role: "user", parts }],
    generationConfig: {
      temperature: 0.2,
      responseMimeType: "application/json",
      responseSchema: schemaParaGemini(schemaEstrito(opts.schema)),
    },
  };

  const modelos = [opts.model, ...GEMINI_MODELOS_GRATUITOS.filter((m) => m !== opts.model)];
  let resp: Response | undefined;
  let raw = "";
  for (let i = 0; i < modelos.length; i++) {
    const url = `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(modelos[i])}:generateContent`;
    try {
      resp = await fetch(url, {
        method: "POST",
        signal: opts.signal,
        headers: {
          "Content-Type": "application/json",
          "x-goog-api-key": opts.key,
        },
        body: JSON.stringify(body),
      });
    } catch (e) {
      if ((e as Error)?.name === "AbortError") throw e;
      return { ok: false, status: 503, error: "Não foi possível conectar ao Gemini. Verifique a rede e tente novamente.", retryable: true };
    }
    raw = await resp.text().catch(() => "");
    if (resp.ok) break;
    if (resp.status !== 404 || i === modelos.length - 1) break;
  }

  if (!resp || !resp.ok) {
    let detalhe = "";
    let statusGrpc = "";
    try {
      const p = JSON.parse(raw);
      detalhe = p?.error?.message || "";
      statusGrpc = p?.error?.status || "";
    } catch { /* texto não-JSON */ }
    console.error("Gemini error", resp?.status, sanitizarErroParaLog(raw, opts.key));
    const status = resp?.status || 502;
    return {
      ok: false,
      status: status === 429 ? 429 : status >= 500 ? status : status === 403 ? 403 : 502,
      error: mensagemAmigavel(status, detalhe, statusGrpc),
      retryable: status === 429 || status >= 500,
    };
  }

  let parsed: any;
  try { parsed = JSON.parse(raw); } catch {
    return { ok: false, status: 502, error: "A resposta do Gemini veio em formato inválido.", retryable: true };
  }
  const text = (parsed?.candidates || [])
    .flatMap((c: any) => c?.content?.parts || [])
    .map((p: any) => p?.text || "")
    .join("")
    .trim();
  const finish = parsed?.candidates?.[0]?.finishReason;
  if (!text) {
    return {
      ok: false,
      status: 502,
      error: finish === "MAX_TOKENS"
        ? "A resposta da IA ficou incompleta por excesso de conteúdo. Reduza anexos ou textos e tente novamente."
        : "A IA retornou uma resposta vazia. Tente novamente.",
      retryable: true,
    };
  }
  return { ok: true, text };
}

export async function gerarJsonEmFluxo(opts: {
  req: Request;
  corsHeaders: Record<string, string>;
  key: string;
  systemPrompt: string;
  userContent: unknown[];
  schemaName: string;
  schema: unknown;
  posProcessar?: (output: any) => any;
  tools?: unknown[];
  model?: string;
}): Promise<Response> {
  const { req, corsHeaders, key } = opts;
  const jsonHeaders = { ...corsHeaders, "Content-Type": "application/json" };
  // tools (ex.: web_search do gateway antigo) não existem no plano gratuito Gemini — ignorados de propósito.
  void opts.tools;
  void opts.schemaName;

  const temImagem = (opts.userContent || []).some((c: any) => c?.type === "input_image" || c?.type === "image_url");
  const model = opts.model || (temImagem ? GEMINI_MODELO_VISAO : GEMINI_MODELO_PADRAO);

  const headers = {
    ...corsHeaders,
    "Content-Type": "application/x-ndjson",
    "Cache-Control": "no-cache",
  };
  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    async start(controller) {
      const send = (obj: unknown) => {
        try { controller.enqueue(encoder.encode(JSON.stringify(obj) + "\n")); } catch { /* fechado */ }
      };
      send({ type: "ping" });
      const ping = setInterval(() => send({ type: "ping" }), 10_000);
      try {
        const result = await chamarGeminiJson({
          key,
          model,
          systemPrompt: opts.systemPrompt,
          userContent: opts.userContent,
          schema: opts.schema,
          signal: req.signal,
        });
        if (!result.ok) {
          send({ type: "error", error: result.error, retryable: result.retryable });
          return;
        }
        try {
          const parsed = JSON.parse(result.text);
          send({ type: "result", output: opts.posProcessar ? opts.posProcessar(parsed) : parsed });
        } catch {
          send({ type: "error", error: "A resposta da IA veio em formato inválido. Tente novamente.", retryable: true });
        }
      } catch (e) {
        if (!req.signal.aborted) {
          console.error("Gemini stream error", (e as Error)?.name || "error");
          send({ type: "error", error: (e as Error).message || "Falha durante a geração com IA.", retryable: true });
        }
      } finally {
        clearInterval(ping);
        try { controller.close(); } catch { /* já fechado */ }
      }
    },
    cancel() { /* abort via req.signal */ },
  });

  // Atalho: se a chave estiver vazia, responde JSON imediato (não deveria ocorrer — callers checam).
  if (!key) {
    return new Response(JSON.stringify({ error: mensagemSemChaveGemini() }), { status: 500, headers: jsonHeaders });
  }

  return new Response(stream, { status: 200, headers });
}

/** Chamada síncrona JSON (ex.: psico-generate) sem NDJSON. */
export async function gerarJsonGemini(opts: {
  key: string;
  systemPrompt: string;
  userContent: unknown[];
  schema: unknown;
  model?: string;
  signal?: AbortSignal;
}): Promise<{ ok: true; output: any } | { ok: false; status: number; error: string }> {
  const result = await chamarGeminiJson({
    key: opts.key,
    model: opts.model || GEMINI_MODELO_PADRAO,
    systemPrompt: opts.systemPrompt,
    userContent: opts.userContent,
    schema: opts.schema,
    signal: opts.signal,
  });
  if (!result.ok) return { ok: false, status: result.status, error: result.error };
  try {
    return { ok: true, output: JSON.parse(result.text) };
  } catch {
    return { ok: false, status: 502, error: "A resposta da IA veio em formato inválido. Tente novamente." };
  }
}

import { ESTIMATIVAS_APR, INTENSIDADES_APR, perfilApr, classificacaoApr } from "./aprErgoPlanilha.ts";
export { SITUACOES_APR, TIPOS_APR } from "./aprErgoPlanilha.ts";
export const MAX_BASE_APR = 6;
export const CAMPOS_APR = ["cenario", "circunstancia", "situacao", "exigencia", "tipo", "medidas", "estimativa", "intensidade", "perfil", "severidade", "classificacao", "recomendacoes"] as const;
export type LinhaApr = Record<typeof CAMPOS_APR[number], string> & { fotos: string[]; funcao_id?: string; funcao_ids?: string[]; funcao_nome?: string; setor_id?: string };
export const CAMPOS_RESUMO_APR = ["atividades", "ambiente"] as const;
export type ResumoApr = Record<typeof CAMPOS_RESUMO_APR[number], string>;
export type PropostaApr = { linhas: LinhaApr[]; fontes_aep: string[]; observacoes: string; cabecalho?: ResumoApr };

export function aplicarResumoApr<T extends ResumoApr>(atual: T, proposta: Partial<ResumoApr> | undefined, substituir: boolean): T {
  const resultado = { ...atual };
  for (const k of CAMPOS_RESUMO_APR) {
    const valor = proposta?.[k]?.trim();
    if (valor && (substituir || !atual[k].trim())) resultado[k] = valor;
  }
  return resultado;
}
export function contarConflitosResumoApr(atual: ResumoApr, proposta?: Partial<ResumoApr>): number {
  return CAMPOS_RESUMO_APR.filter((k) => atual[k].trim() && proposta?.[k]?.trim() && atual[k].trim() !== proposta[k]?.trim()).length;
}
/** Conduta administrativa fixa (matriz de conduta da APR-HO); acompanha sempre a classificação calculada. */
export const CONDUTAS_APR: Record<string, string> = {
  "SEM RISCO": "Nenhuma ação é requerida e nenhum registro documental precisa ser mantido.",
  BAIXO: "Há medidas de controle eficientes. Devem ser gerenciadas na busca de melhorias contínuas.",
  "MÉDIO": "Devem ser gerenciadas na busca de melhorias contínuas e medidas de controle implementadas.",
  ALTO: "Faz-se necessária recomendação para o controle da exposição, com investigação da ocorrência do risco e plano de ação (AET + Plano de ação).",
  "MUITO ALTO": "Faz-se necessária recomendação para o controle da exposição, com investigação da ocorrência do risco e plano de ação (AET + Plano de ação).",
};
export function condutaApr(classificacao: string): string {
  return CONDUTAS_APR[classificacao === "Não se Aplica" ? "SEM RISCO" : classificacao] || "";
}
const CONDUTAS_UNICAS = [...new Set(Object.values(CONDUTAS_APR))];
/** Remove a conduta anterior do início e insere a do nível atual, preservando o texto restante. */
export function sincronizarCondutaApr(recomendacoes: string, classificacao: string): string {
  if (classificacao === "ALTO" || classificacao === "MUITO ALTO") return condutaApr(classificacao);
  let resto = recomendacoes.trim(); let achou = true;
  while (achou) { achou = false; for (const c of CONDUTAS_UNICAS) if (resto.startsWith(c)) { resto = resto.slice(c.length).trim(); achou = true; } }
  return [condutaApr(classificacao), resto].filter(Boolean).join("\n");
}

/** Merge is explicitly field-level: photos and unmatched manual rows always survive. */
export function aplicarPropostaApr(atuais: LinhaApr[], propostas: LinhaApr[], substituir: boolean): LinhaApr[] {
  return Array.from({ length: Math.max(atuais.length, propostas.length) }, (_, i) => {
    const atual = atuais[i]; const nova = propostas[i];
    const campos = Object.fromEntries(CAMPOS_APR.map((k) => [k, nova?.[k]?.trim() && (substituir || !atual?.[k]?.trim()) ? nova[k] : atual?.[k] || ""])) as Record<typeof CAMPOS_APR[number], string>;
    const vinculo = atual?.circunstancia.trim() && !substituir ? atual : nova?.funcao_id || nova?.funcao_ids?.length ? nova : atual;
    return recalcularLinhaApr({ ...campos, fotos: atual?.fotos || [], funcao_id: vinculo?.funcao_id, funcao_ids: vinculo?.funcao_ids, funcao_nome: vinculo?.funcao_nome, setor_id: vinculo?.setor_id });
  });
}
export function contarConflitosApr(atuais: LinhaApr[], propostas: LinhaApr[]): number {
  return propostas.reduce((n, l, i) => n + CAMPOS_APR.filter((k) => atuais[i]?.[k]?.trim() && l[k]?.trim() && atuais[i][k].trim() !== l[k].trim()).length, 0);
}
/** No quantity cap: exact function/sector identity and distinct technical circumstances only. */
export function cenariosValidosApr<T extends { funcao_id?: string; funcao_ids?: string[]; setor_id?: string; circunstancia: string; situacao: string; exigencia: string }>(linhas: T[], setorId: string, funcaoIds: string[]): T[] {
  const vistos = new Set<string>();
  const normalizar = (s: string) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/\s+/g, " ").trim();
  return linhas.filter((l) => {
    const ids = l.funcao_ids?.length ? l.funcao_ids : l.funcao_id ? [l.funcao_id] : [];
    if (l.setor_id !== setorId || !ids.length || ids.some((id) => !funcaoIds.includes(id)) || !l.circunstancia.trim() || !l.situacao || !l.exigencia) return false;
    const chave = JSON.stringify([normalizar(l.circunstancia), normalizar(l.situacao), normalizar(l.exigencia)]);
    if (vistos.has(chave)) return false;
    vistos.add(chave); return true;
  });
}

/** Generated content only: remove registry names without touching saved/manual cells. */
export function circunstanciaTecnicaApr(texto: unknown, nomes: string[]): string {
  if (typeof texto !== "string") return "";
  let resultado = texto;
  for (const nome of [...nomes].filter(Boolean).sort((a, b) => b.length - a.length)) {
    const literal = nome.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    resultado = resultado.replace(new RegExp(`(?<![\\p{L}\\p{N}])${literal}(?![\\p{L}\\p{N}])`, "giu"), "");
  }
  return resultado.replace(/^\s*[-—–:;,/]+\s*/, "").replace(/\s+/g, " ").trim();
}
export function formulariosCompativeisApr<T extends { setor_ids: string[]; dados: unknown }>(formularios: T[], setorId: string, funcaoIds: string[]): T[] {
  return formularios.filter((f) => {
    if (f.setor_ids.length !== 1 || f.setor_ids[0] !== setorId) return false;
    const dados = f.dados as { funcoes?: string[] } | null;
    return !dados?.funcoes?.length || dados.funcoes.every((id) => funcaoIds.includes(id));
  });
}

/** Recalcula as colunas automáticas exatamente como Formulario!K e M. */
export function recalcularLinhaApr<T extends { estimativa: string; intensidade: string; severidade: string; perfil: string; classificacao: string; recomendacoes?: string }>(l: T): T {
  const perfil = perfilApr(l.estimativa, l.intensidade);
  const classificacao = classificacaoApr(perfil, l.severidade);
  return { ...l, perfil, classificacao, ...(typeof l.recomendacoes === "string" ? { recomendacoes: sincronizarCondutaApr(l.recomendacoes, classificacao) } : {}) };
}

/** Only unambiguous single D/I marks from Anexo 01 are transferred, mapped by level to the spreadsheet options. */
export function classificacoesSalvasApr(marcas: Record<string, string>) {
  const unico = (prefixo: string, opcoes: [string, number][]) => {
    const ativos = Object.entries(marcas).filter(([k, v]) => new RegExp(`^${prefixo}[1-5]$`).test(k) && String(v).trim());
    return ativos.length === 1 ? opcoes[Number(ativos[0][0].slice(1)) - 1]?.[0] || "" : "";
  };
  return { estimativa: unico("D", ESTIMATIVAS_APR), intensidade: unico("I", INTENSIDADES_APR) };
}

