const idx = <T extends unknown[]>(tab: T[], valor: string, col = 0, ret = 1) => tab.find((r) => r[col] === valor)?.[ret] as number | undefined;
/** Formulario!K11: VLOOKUP(índice tempo × índice intensidade, Tabela!M:O, 2). */
export function perfilApr(estimativa: string, intensidade: string): string {
  const t = idx(ESTIMATIVAS_APR, estimativa), i = idx(INTENSIDADES_APR, intensidade);
  return t && i ? PERFIS_APR.find((p) => p[0] === t * i)?.[1] || "" : "";
}
/** Formulario!M11: VLOOKUP(índice perfil × índice severidade, Tabela!U:V, 2). */
export function classificacaoApr(perfil: string, severidade: string): string {
  const p = PERFIS_APR.find((r) => r[1] === perfil)?.[2], s = idx(SEVERIDADES_APR, severidade, 1, 2);
  return p && s ? CATEGORIAS_APR.find((c) => c[0] === p * s)?.[1] || "" : "";
}
export const exigenciasDaSituacao = (situacao: string) => EXIGENCIAS_APR.filter((e) => e[0] === situacao).map((e) => e[1]);
